// Map diagrams: things laid out in space, drawn to scale. Grids of values
// (occupancy, cost, a heat map, an array's cells), shapes (boxes, circles,
// paths, points, text) in layers, and optionally steps through time (a
// search expanding, ships moving). Generated by a project's own tools from
// real data as often as written by hand.
//
//   type: map
//   title: A route round a wall
//   view: [0, 0, 4000, 3000]        # world rectangle shown: x0 y0 x1 y1 (y grows down)
//   unit: elmos                     # for the scale bar and the hover readout
//   layers:
//     - id: clearance
//       label: Clearance
//       grid:
//         origin: [0, 0]            # world corner of cell (0, 0)
//         cell: 64                  # cell size; or cell: [w, h]
//         values: |                 # rows, whitespace-separated; "." is empty
//           0 64 128 .
//           0 0 64 128
//         palette: heat             # heat, cool, green, red, purple, grey, or [[value, "#hex"], …]
//         range: [0, 320]
//         legend: elmos to the nearest blocked cell
//         labels: true              # print each value in its cell; or rows of text like values
//     - id: hulls
//       label: Hulls
//       shapes:
//         - { rect: [1200, 900, 260, 120], angle: 0.3, label: Phalanx, tone: bad }
//         - { circle: [300, 300, 90], tone: accent }
//         - { line: [[0, 0], [500, 200]], tone: accent, arrow: true, dashed: true, width: 2 }
//         - { point: [500, 200], marker: cross, label: goal }
//         - { text: [100, 100], label: "tile (0, 0)" }
//   steps:                          # optional: each replaces or adds layers by id
//     - label: 50 expansions
//       view: [0, 0, 2000, 1500]    # optional: this step looks elsewhere
//       layers: [{ id: closed, grid: { … } }]
//
// A shape's `key` puts it in the legend (in its tone and line style); a
// layer whose shapes have keys lists those instead of the layer's name.
//
// Tones: fg, muted, accent, good, bad, warn, quiet, or a "#hex" colour. On a
// page the map is still; Full screen pans and zooms. Steps get a slider; the
// rendered PNG shows the steps side by side (`columns`, default 2).

import { useEffect, useMemo, useRef, useState, type PointerEvent as ReactPointerEvent, type ReactElement } from "react";

type Point = [number, number];

export interface GridSpec {
  origin?: Point;
  cell: number | Point;
  /** Rows of whitespace-separated numbers; "." for an empty cell. */
  values: string | (number | null)[][];
  palette?: string | [number, string][];
  range?: Point;
  opacity?: number;
  legend?: string;
  /** true: print the values; or rows of text in the same shape as values. */
  labels?: boolean | string | string[][];
  /** Draw the cell borders. */
  outline?: boolean;
}

export interface ShapeSpec {
  rect?: [number, number, number, number];
  angle?: number;
  circle?: [number, number, number];
  line?: Point[];
  point?: Point;
  text?: Point;
  marker?: "dot" | "cross" | "ring" | "square";
  label?: string;
  /** An entry for this shape in the legend, drawn in its tone and line style. */
  key?: string;
  tone?: string;
  fill?: string;
  dashed?: boolean;
  arrow?: boolean;
  width?: number;
}

export interface LayerSpec {
  id: string;
  label?: string;
  hidden?: boolean;
  grid?: GridSpec;
  shapes?: ShapeSpec[];
}

export interface MapSpec {
  type: "map";
  title?: string;
  view: [number, number, number, number];
  unit?: string;
  /** Scale bar length in world units (default: a round tenth of the view). */
  scale?: number;
  /** Drawing width for the rendered image, px. */
  width?: number;
  layers?: LayerSpec[];
  /** Each step may also look at another part of the world (`view`). */
  steps?: { label: string; view?: [number, number, number, number]; layers?: LayerSpec[] }[];
  /** Steps per row in the rendered image. */
  columns?: number;
}

type Theme = "light" | "dark";

const TONES: Record<Theme, Record<string, string>> = {
  light: { fg: "#1f2328", muted: "#59636e", accent: "#0969da", good: "#1a7f37", bad: "#cf222e", warn: "#bf8700", quiet: "#8c959f", purple: "#8250df" },
  dark: { fg: "#e6edf3", muted: "#9198a1", accent: "#4493f8", good: "#3fb950", bad: "#f85149", warn: "#d29922", quiet: "#6e7681", purple: "#ab7df8" },
};

const PALETTES: Record<string, string[]> = {
  heat: ["#fff7bc", "#fec44f", "#fe9929", "#ec7014", "#cc4c02", "#8c2d04"],
  cool: ["#f7fbff", "#c6dbef", "#6baed6", "#2171b5", "#08306b"],
  green: ["#f7fcf5", "#c7e9c0", "#74c476", "#238b45", "#00441b"],
  red: ["#fff5f0", "#fcbba1", "#fb6a4a", "#cb181d", "#67000d"],
  purple: ["#fcfbfd", "#dadaeb", "#9e9ac8", "#6a51a3", "#3f007d"],
  grey: ["#ffffff", "#d9d9d9", "#969696", "#525252", "#000000"],
  // Low values strong: distance to an obstacle, time left.
  room: ["#b2182b", "#ef8a62", "#fddbc7", "#f7f7f7", "#d1e5f0"],
};

function tone(theme: Theme, t: string | undefined, fallback = "fg"): string {
  if (t?.startsWith("#")) return t;
  return TONES[theme][t ?? fallback] ?? TONES[theme][fallback];
}

function parseValues(values: GridSpec["values"]): (number | null)[][] {
  if (Array.isArray(values)) return values;
  return values.trim().split(/\r?\n/).map((row) => row.trim().split(/\s+/).map((v) => (v === "." || v === "" ? null : Number(v))));
}

function parseLabels(labels: GridSpec["labels"], values: (number | null)[][]): (string | null)[][] | null {
  if (!labels) return null;
  if (labels === true) return values.map((row) => row.map((v) => (v === null ? null : formatValue(v))));
  if (Array.isArray(labels)) return labels;
  return labels.trim().split(/\r?\n/).map((row) => row.trim().split(/\s+/).map((v) => (v === "." ? null : v)));
}

function formatValue(v: number): string {
  return Number.isInteger(v) ? String(v) : Math.abs(v) >= 10 ? v.toFixed(0) : v.toFixed(2);
}

function hexToRgb(hex: string): [number, number, number] {
  const h = hex.replace("#", "");
  const n = parseInt(h.length === 3 ? h.split("").map((c) => c + c).join("") : h, 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

/** value → colour for a grid. */
function colourScale(grid: GridSpec, values: (number | null)[][]): (v: number) => [number, number, number] {
  const flat = values.flat().filter((v): v is number => v !== null);
  const [lo, hi] = grid.range ?? [Math.min(0, ...flat), Math.max(1, ...flat)];
  if (Array.isArray(grid.palette)) {
    const stops = [...grid.palette].sort((a, b) => a[0] - b[0]).map(([v, c]) => [v, hexToRgb(c)] as const);
    return (v) => {
      // Stops are exact categories when the value matches one, otherwise interpolated.
      let i = stops.findIndex(([s]) => s >= v);
      if (i < 0) return stops[stops.length - 1][1];
      if (i === 0 || stops[i][0] === v) return stops[i][1];
      const [a, ca] = stops[i - 1];
      const [b, cb] = stops[i];
      const t = (v - a) / (b - a || 1);
      return [0, 1, 2].map((k) => Math.round(ca[k] + (cb[k] - ca[k]) * t)) as [number, number, number];
    };
  }
  const colours = (PALETTES[grid.palette ?? "heat"] ?? PALETTES.heat).map(hexToRgb);
  return (v) => {
    const t = Math.max(0, Math.min(1, (v - lo) / (hi - lo || 1))) * (colours.length - 1);
    const i = Math.min(colours.length - 2, Math.floor(t));
    const f = t - i;
    return [0, 1, 2].map((k) => Math.round(colours[i][k] + (colours[i + 1][k] - colours[i][k]) * f)) as [number, number, number];
  };
}

interface Prepared {
  id: string;
  label?: string;
  hidden?: boolean;
  grid?: {
    spec: GridSpec;
    origin: Point;
    cell: Point;
    values: (number | null)[][];
    labels: (string | null)[][] | null;
    image: string;
    colour: (v: number) => [number, number, number];
  };
  shapes: ShapeSpec[];
}

/** A grid drawn once into an image, one pixel a cell; the SVG scales it without smoothing. */
function prepare(layer: LayerSpec): Prepared {
  const out: Prepared = { id: layer.id, label: layer.label, hidden: layer.hidden, shapes: layer.shapes ?? [] };
  const g = layer.grid;
  if (g) {
    const values = parseValues(g.values);
    const rows = values.length;
    const cols = Math.max(0, ...values.map((r) => r.length));
    const colour = colourScale(g, values);
    let image = "";
    if (typeof document !== "undefined" && rows && cols) {
      const canvas = document.createElement("canvas");
      canvas.width = cols;
      canvas.height = rows;
      const ctx = canvas.getContext("2d")!;
      const data = ctx.createImageData(cols, rows);
      const alpha = Math.round(255 * (g.opacity ?? 1));
      values.forEach((row, y) => row.forEach((v, x) => {
        if (v === null || Number.isNaN(v)) return;
        const [r, gg, b] = colour(v);
        const o = (y * cols + x) * 4;
        data.data.set([r, gg, b, alpha], o);
      }));
      ctx.putImageData(data, 0, 0);
      image = canvas.toDataURL();
    }
    const cell: Point = Array.isArray(g.cell) ? g.cell : [g.cell, g.cell];
    out.grid = { spec: g, origin: g.origin ?? [0, 0], cell, values, labels: parseLabels(g.labels, values), image, colour };
  }
  return out;
}

function layersAt(spec: MapSpec, step: number): LayerSpec[] {
  const layers = [...(spec.layers ?? [])];
  const s = spec.steps?.[step];
  for (const l of s?.layers ?? []) {
    const i = layers.findIndex((x) => x.id === l.id);
    if (i >= 0) layers[i] = { ...layers[i], ...l };
    else layers.push(l);
  }
  return layers;
}

export function MapDiagram({ spec, theme, fixed, fullScreen = false }: { spec: MapSpec; theme: Theme; fixed: boolean; fullScreen?: boolean }) {
  const steps = spec.steps?.length ?? 0;
  if (fixed && steps) {
    const columns = Math.min(steps, spec.columns ?? 2);
    const width = Math.round((spec.width ?? 1100) / columns);
    return (
      <div className={`cd cd-${theme} cd-map cd-fixed`} style={{ width: width * columns + 24 * (columns - 1) + 32 }}>
        {spec.title && <div className="cd-map-title">{spec.title}</div>}
        <div className="cd-map-panels" style={{ gridTemplateColumns: `repeat(${columns}, ${width}px)` }}>
          {spec.steps!.map((s, i) => (
            <div key={i}>
              <div className="cd-map-step">{i + 1}. {s.label}</div>
              <MapView spec={spec} theme={theme} step={i} width={width} interactive={false} hiddenIds={new Set()} />
            </div>
          ))}
        </div>
        <Legend spec={spec} theme={theme} step={steps - 1} hidden={new Set()} />
      </div>
    );
  }
  return <MapPanel spec={spec} theme={theme} fixed={fixed} fullScreen={fullScreen} />;
}

function MapPanel({ spec, theme, fixed, fullScreen }: { spec: MapSpec; theme: Theme; fixed: boolean; fullScreen: boolean }) {
  const steps = spec.steps?.length ?? 0;
  const [step, setStep] = useState(0);
  const [playing, setPlaying] = useState(false);
  const [hidden, setHidden] = useState(() => new Set((spec.layers ?? []).filter((l) => l.hidden).map((l) => l.id)));
  const box = useRef<HTMLDivElement>(null);
  const [width, setWidth] = useState(spec.width ?? 1100);
  useEffect(() => {
    if (fixed || !box.current) return;
    const observer = new ResizeObserver(([entry]) => setWidth(Math.max(200, entry.contentRect.width)));
    observer.observe(box.current);
    return () => observer.disconnect();
  }, [fixed]);
  useEffect(() => {
    if (!playing || !steps) return;
    const timer = setInterval(() => setStep((s) => (s + 1) % steps), 900);
    return () => clearInterval(timer);
  }, [playing, steps]);
  const named = useMemo(() => {
    const ids = new Map<string, string>();
    for (const l of [...(spec.layers ?? []), ...(spec.steps ?? []).flatMap((s) => s.layers ?? [])]) if (l.label && !ids.has(l.id)) ids.set(l.id, l.label);
    return [...ids];
  }, [spec]);
  return (
    <div className={`cd cd-${theme} cd-map${fixed ? " cd-fixed" : ""}`} style={fixed ? { width: (spec.width ?? 1100) + 32 } : undefined}>
      {fixed && spec.title && <div className="cd-map-title">{spec.title}</div>}
      {!fixed && (steps > 0 || named.length > 1) && (
        <div className="cd-map-tools">
          {steps > 0 && <>
            <button type="button" className="cd-view-button" onClick={() => setPlaying(!playing)} aria-label={playing ? "Pause" : "Play"}>{playing ? "❚❚" : "▶"}</button>
            <input type="range" min={0} max={steps - 1} value={step} aria-label="Step" onChange={(e) => { setPlaying(false); setStep(Number(e.target.value)); }} />
            <span className="cd-map-step">{step + 1}/{steps} · {spec.steps![step].label}</span>
          </>}
          {named.length > 1 && <span className="cd-map-chips">
            {named.map(([id, label]) => (
              <label key={id} className="cd-map-chip">
                <input type="checkbox" checked={!hidden.has(id)} onChange={() => setHidden((h) => { const n = new Set(h); if (n.has(id)) n.delete(id); else n.add(id); return n; })} />
                {label}
              </label>
            ))}
          </span>}
        </div>
      )}
      <div ref={box} className={fullScreen ? "cd-map-full" : undefined}>
        <MapView spec={spec} theme={theme} step={step} width={fixed ? spec.width ?? 1100 : width} interactive={!fixed} zoomable={fullScreen} hiddenIds={hidden} />
      </div>
      <Legend spec={spec} theme={theme} step={step} hidden={hidden} />
    </div>
  );
}

function MapView({ spec, theme, step, width, interactive, zoomable = false, hiddenIds }: { spec: MapSpec; theme: Theme; step: number; width: number; interactive: boolean; zoomable?: boolean; hiddenIds: Set<string> }) {
  const layers = useMemo(() => layersAt(spec, step).map(prepare), [spec, step]);
  const [x0, y0, x1, y1] = spec.steps?.[step]?.view ?? spec.view;
  const [view, setView] = useState<[number, number, number, number]>([x0, y0, x1 - x0, y1 - y0]);
  useEffect(() => setView([x0, y0, x1 - x0, y1 - y0]), [x0, y0, x1, y1]);
  const height = Math.round((width * (y1 - y0)) / (x1 - x0));
  // World units per screen pixel: text and strokes keep their screen size.
  const px = view[2] / width;
  const [hover, setHover] = useState<{ x: number; y: number; sx: number; sy: number } | null>(null);
  const drag = useRef<{ x: number; y: number; view: typeof view } | null>(null);
  const svg = useRef<SVGSVGElement>(null);
  const toWorld = (e: { clientX: number; clientY: number }) => {
    const r = svg.current!.getBoundingClientRect();
    return { x: view[0] + ((e.clientX - r.left) / r.width) * view[2], y: view[1] + ((e.clientY - r.top) / r.height) * view[3], sx: e.clientX - r.left, sy: e.clientY - r.top };
  };
  useEffect(() => {
    const el = svg.current;
    if (!el || !zoomable) return;
    const wheel = (e: WheelEvent) => {
      e.preventDefault();
      const r = el.getBoundingClientRect();
      const f = Math.exp(e.deltaY * 0.0015);
      setView(([vx, vy, vw, vh]) => {
        const mx = vx + ((e.clientX - r.left) / r.width) * vw;
        const my = vy + ((e.clientY - r.top) / r.height) * vh;
        return [mx - (mx - vx) * f, my - (my - vy) * f, vw * f, vh * f];
      });
    };
    el.addEventListener("wheel", wheel, { passive: false });
    return () => el.removeEventListener("wheel", wheel);
  }, [zoomable]);
  const visible = layers.filter((l) => !hiddenIds.has(l.id));
  const font = 12 * px;
  return (
    <div className="cd-map-canvas" style={{ position: "relative" }}>
      <svg
        ref={svg}
        className="cd-map-svg"
        width={zoomable ? "100%" : width}
        height={zoomable ? "100%" : height}
        viewBox={view.join(" ")}
        preserveAspectRatio="xMidYMid meet"
        onPointerMove={interactive ? (e: ReactPointerEvent<SVGSVGElement>) => {
          const w = toWorld(e);
          if (drag.current) {
            const r = svg.current!.getBoundingClientRect();
            const d = drag.current;
            const dx = ((e.clientX - d.x) / r.width) * d.view[2];
            const dy = ((e.clientY - d.y) / r.height) * d.view[3];
            setView([d.view[0] - dx, d.view[1] - dy, d.view[2], d.view[3]]);
          }
          setHover(w);
        } : undefined}
        onPointerLeave={interactive ? () => { setHover(null); drag.current = null; } : undefined}
        onPointerDown={zoomable ? (e) => { drag.current = { x: e.clientX, y: e.clientY, view }; (e.target as Element).setPointerCapture?.(e.pointerId); } : undefined}
        onPointerUp={zoomable ? () => { drag.current = null; } : undefined}
        style={{ cursor: zoomable ? "grab" : interactive ? "crosshair" : undefined, display: "block", touchAction: zoomable ? "none" : undefined }}
      >
        <rect x={x0} y={y0} width={x1 - x0} height={y1 - y0} fill="var(--cd-map-bg)" />
        {visible.map((l) => l.grid && <GridLayer key={`g-${l.id}`} layer={l} theme={theme} px={px} />)}
        {visible.map((l) => l.shapes.length > 0 && <g key={`s-${l.id}`}>{l.shapes.map((s, i) => <Shape key={i} s={s} theme={theme} px={px} font={font} />)}</g>)}
        <ScaleBar spec={spec} view={view} px={px} theme={theme} />
      </svg>
      {interactive && hover && <Readout spec={spec} layers={visible} at={hover} width={width} />}
    </div>
  );
}

function GridLayer({ layer, theme, px }: { layer: Prepared; theme: Theme; px: number }) {
  const g = layer.grid!;
  const rows = g.values.length;
  const cols = Math.max(0, ...g.values.map((r) => r.length));
  const [ox, oy] = g.origin;
  const [cw, ch] = g.cell;
  return (
    <g>
      {g.image && <image href={g.image} x={ox} y={oy} width={cols * cw} height={rows * ch} preserveAspectRatio="none" style={{ imageRendering: "pixelated" }} />}
      {g.spec.outline && <g stroke={tone(theme, "quiet")} strokeWidth={px * 0.6} opacity={0.6}>
        {Array.from({ length: cols + 1 }, (_, i) => <line key={`c${i}`} x1={ox + i * cw} y1={oy} x2={ox + i * cw} y2={oy + rows * ch} />)}
        {Array.from({ length: rows + 1 }, (_, i) => <line key={`r${i}`} x1={ox} y1={oy + i * ch} x2={ox + cols * cw} y2={oy + i * ch} />)}
      </g>}
      {g.labels && cw / px >= 14 && <g fontSize={Math.min(11 * px, ch * 0.42)} textAnchor="middle" dominantBaseline="central" fontFamily="ui-monospace, SFMono-Regular, Menlo, monospace">
        {g.labels.flatMap((row, y) => row.map((t, x) => {
          if (t === null || t === undefined) return null;
          const v = g.values[y]?.[x];
          // Dark text on light cells, light on dark.
          const [r, gg, b] = v === null || v === undefined ? [255, 255, 255] : g.colour(v);
          const light = 0.299 * r + 0.587 * gg + 0.114 * b > 140;
          return <text key={`${x},${y}`} x={ox + (x + 0.5) * cw} y={oy + (y + 0.5) * ch} fill={light ? "#1f2328" : "#ffffff"}>{t}</text>;
        }))}
      </g>}
    </g>
  );
}

function Shape({ s, theme, px, font }: { s: ShapeSpec; theme: Theme; px: number; font: number }) {
  const stroke = tone(theme, s.tone);
  const width = (s.width ?? 1.5) * px;
  const dash = s.dashed ? `${6 * px} ${4 * px}` : undefined;
  const label = (x: number, y: number, anchor: "start" | "middle" = "start") => s.label && (
    <text x={x} y={y} fontSize={font} fill={stroke} textAnchor={anchor} paintOrder="stroke" stroke="var(--cd-map-bg)" strokeWidth={3 * px} strokeLinejoin="round">{s.label}</text>
  );
  if (s.rect) {
    const [cx, cy, w, h] = s.rect;
    const deg = ((s.angle ?? 0) * 180) / Math.PI;
    return <g>
      <rect x={cx - w / 2} y={cy - h / 2} width={w} height={h} transform={`rotate(${deg} ${cx} ${cy})`} fill={s.fill ?? stroke} fillOpacity={s.fill ? 1 : 0.18} stroke={stroke} strokeWidth={width} strokeDasharray={dash} />
      {label(cx, cy - Math.max(w, h) / 2 - 4 * px, "middle")}
    </g>;
  }
  if (s.circle) {
    const [cx, cy, r] = s.circle;
    return <g>
      <circle cx={cx} cy={cy} r={r} fill={s.fill ?? "none"} stroke={stroke} strokeWidth={width} strokeDasharray={dash} />
      {label(cx + r + 4 * px, cy)}
    </g>;
  }
  if (s.line && s.line.length > 1) {
    const pts = s.line;
    const d = pts.map(([x, y], i) => `${i ? "L" : "M"}${x} ${y}`).join(" ");
    const [ax, ay] = pts[pts.length - 2];
    const [bx, by] = pts[pts.length - 1];
    const a = Math.atan2(by - ay, bx - ax);
    const head = 9 * px;
    return <g>
      <path d={d} fill="none" stroke={stroke} strokeWidth={width} strokeDasharray={dash} strokeLinejoin="round" strokeLinecap="round" />
      {s.arrow && <path d={`M${bx} ${by} L${bx - head * Math.cos(a - 0.4)} ${by - head * Math.sin(a - 0.4)} L${bx - head * Math.cos(a + 0.4)} ${by - head * Math.sin(a + 0.4)} Z`} fill={stroke} />}
      {label(pts[Math.floor(pts.length / 2)][0] + 4 * px, pts[Math.floor(pts.length / 2)][1] - 4 * px)}
    </g>;
  }
  if (s.point) {
    const [x, y] = s.point;
    const r = 4 * px;
    const mark = s.marker ?? "dot";
    return <g>
      {mark === "dot" && <circle cx={x} cy={y} r={r} fill={stroke} />}
      {mark === "ring" && <circle cx={x} cy={y} r={r * 1.6} fill="none" stroke={stroke} strokeWidth={width} />}
      {mark === "square" && <rect x={x - r} y={y - r} width={2 * r} height={2 * r} fill={stroke} />}
      {mark === "cross" && <path d={`M${x - r * 1.5} ${y - r * 1.5} L${x + r * 1.5} ${y + r * 1.5} M${x - r * 1.5} ${y + r * 1.5} L${x + r * 1.5} ${y - r * 1.5}`} stroke={stroke} strokeWidth={width * 1.4} />}
      {label(x + 7 * px, y - 5 * px)}
    </g>;
  }
  if (s.text) {
    const [x, y] = s.text;
    return <text x={x} y={y} fontSize={font} fill={stroke} paintOrder="stroke" stroke="var(--cd-map-bg)" strokeWidth={3 * px} strokeLinejoin="round">{s.label}</text>;
  }
  return null;
}

function ScaleBar({ spec, view, px, theme }: { spec: MapSpec; view: [number, number, number, number]; px: number; theme: Theme }) {
  const target = spec.scale ?? niceLength(view[2] / 6);
  const x = view[0] + 14 * px;
  const y = view[1] + view[3] - 14 * px;
  const c = tone(theme, "muted");
  return <g>
    <path d={`M${x} ${y - 4 * px} V${y} H${x + target} V${y - 4 * px}`} fill="none" stroke={c} strokeWidth={1.5 * px} />
    <text x={x + target / 2} y={y - 6 * px} fontSize={11 * px} fill={c} textAnchor="middle" paintOrder="stroke" stroke="var(--cd-map-bg)" strokeWidth={3 * px}>{target} {spec.unit ?? ""}</text>
  </g>;
}

function niceLength(v: number): number {
  const p = 10 ** Math.floor(Math.log10(v));
  return [1, 2, 5, 10].map((m) => m * p).reduce((best, x) => (Math.abs(x - v) < Math.abs(best - v) ? x : best));
}

/** What is under the pointer: its position, each visible grid's cell value, and shapes containing it. */
function Readout({ spec, layers, at, width }: { spec: MapSpec; layers: Prepared[]; at: { x: number; y: number; sx: number; sy: number }; width: number }) {
  const rows: string[] = [`${Math.round(at.x)}, ${Math.round(at.y)} ${spec.unit ?? ""}`];
  for (const l of layers) {
    if (l.grid) {
      const { origin, cell, values, labels } = l.grid;
      const cx = Math.floor((at.x - origin[0]) / cell[0]);
      const cy = Math.floor((at.y - origin[1]) / cell[1]);
      const v = values[cy]?.[cx];
      if (v !== undefined && v !== null) rows.push(`${l.label ?? l.id}: ${labels?.[cy]?.[cx] ?? formatValue(v)} (cell ${cx}, ${cy})`);
    }
    for (const s of l.shapes) {
      if (s.label && hit(s, at.x, at.y)) rows.push(`${l.label ?? l.id}: ${s.label}`);
    }
  }
  const left = at.sx > width * 0.6;
  return <div className="cd-map-readout" style={{ top: at.sy + 14, ...(left ? { right: width - at.sx + 14 } : { left: at.sx + 14 }) }}>
    {rows.slice(0, 8).map((r, i) => <div key={i}>{r}</div>)}
  </div>;
}

function hit(s: ShapeSpec, x: number, y: number): boolean {
  if (s.rect) {
    const [cx, cy, w, h] = s.rect;
    const a = -(s.angle ?? 0);
    const dx = x - cx, dy = y - cy;
    const lx = dx * Math.cos(a) - dy * Math.sin(a);
    const ly = dx * Math.sin(a) + dy * Math.cos(a);
    return Math.abs(lx) <= w / 2 && Math.abs(ly) <= h / 2;
  }
  if (s.circle) return Math.hypot(x - s.circle[0], y - s.circle[1]) <= s.circle[2];
  return false;
}

function Legend({ spec, theme, step, hidden }: { spec: MapSpec; theme: Theme; step: number; hidden: Set<string> }) {
  const layers = layersAt(spec, step).filter((l) => !hidden.has(l.id));
  const items: ReactElement[] = [];
  for (const l of layers) {
    if (l.grid?.legend) {
      const g = l.grid;
      const values = parseValues(g.values);
      const colour = colourScale(g, values);
      const flat = values.flat().filter((v): v is number => v !== null);
      const [lo, hi] = g.range ?? [Math.min(0, ...flat), Math.max(1, ...flat)];
      const discrete = Array.isArray(g.palette);
      items.push(<span key={l.id} className="cd-map-legend-item">
        {discrete
          ? (g.palette as [number, string][]).map(([v, c]) => <span key={v} className="cd-map-swatch" style={{ background: c }} title={String(v)} />)
          : <span className="cd-map-ramp" style={{ background: `linear-gradient(to right, ${Array.from({ length: 6 }, (_, i) => `rgb(${colour(lo + ((hi - lo) * i) / 5).join(",")})`).join(",")})` }} />}
        {!discrete && <span className="cd-map-muted">{formatValue(lo)}–{formatValue(hi)}</span>}
        {g.legend}
      </span>);
    }
    const keyed = (l.shapes ?? []).filter((s) => s.key);
    for (const s of keyed) {
      const c = tone(theme, s.tone);
      items.push(<span key={`${l.id}-${s.key}`} className="cd-map-legend-item">
        <svg width="22" height="12" aria-hidden="true">{s.line
          ? <line x1="1" y1="6" x2="21" y2="6" stroke={c} strokeWidth={Math.max(1.5, s.width ?? 1.5)} strokeDasharray={s.dashed ? "4 3" : undefined} />
          : s.rect ? <rect x="3" y="1" width="16" height="10" fill={c} fillOpacity={0.25} stroke={c} />
          : <circle cx="11" cy="6" r="4" fill={c} />}</svg>
        {s.key}
      </span>);
    }
    const tones = [...new Set((l.shapes ?? []).map((s) => s.tone ?? "fg"))];
    if (!keyed.length && l.label && (l.shapes?.length ?? 0) > 0 && !l.grid) {
      items.push(<span key={`${l.id}-s`} className="cd-map-legend-item">
        {tones.map((t) => <span key={t} className="cd-map-swatch" style={{ background: tone(theme, t) }} />)}
        {l.label}
      </span>);
    }
  }
  return items.length ? <div className="cd-map-legend">{items}</div> : null;
}
